fn rust_owned_image_style_value_kind(
    filtered_input: &[u8],
    filtered_input_string: &str,
) -> Option<RustOwnedStyleValueKind> {
    if let Some(value) = rust_owned_image_set_style_value_kind(filtered_input, filtered_input_string) {
        return Some(value);
    }

    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let [component_value] = strip_whitespace(&component_values) else {
        return None;
    };

    if component_value_parse_as_image_url(component_value) {
        return Some(RustOwnedStyleValueKind::Image(RustOwnedImage {
            kind: RustOwnedImageKind::Url,
            source: serialize_component_values_for_reparsing(
                std::slice::from_ref(component_value),
                filtered_input_string,
            )?,
        }));
    }

    if let ComponentValue::Function(function) = component_value
        && component_value_parse_as_image_gradient(component_value)
    {
        return Some(RustOwnedStyleValueKind::Image(RustOwnedImage {
            kind: RustOwnedImageKind::Gradient {
                function_name: function.name.clone(),
            },
            source: serialize_component_values_for_reparsing(
                std::slice::from_ref(component_value),
                filtered_input_string,
            )?,
        }));
    }

    None
}

fn rust_owned_image_set_style_value_kind(
    filtered_input: &[u8],
    filtered_input_string: &str,
) -> Option<RustOwnedStyleValueKind> {
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let component_values = strip_whitespace(&component_values);

    let [ComponentValue::Function(function)] = component_values else {
        return None;
    };

    if !function.name.eq_ignore_ascii_case("image-set") && !function.name.eq_ignore_ascii_case("-webkit-image-set") {
        return None;
    }

    // https://drafts.csswg.org/css-images-4/#image-set-notation
    // image-set() = image-set( <image-set-option># )
    // <image-set-option> = [ <image> | <string> ] [ <resolution> || type(<string>) ]
    // https://compat.spec.whatwg.org/#css-%27-webkit-image-set%27-alias
    // Implementations must accept -webkit-image-set() as a parse-time alias of image-set().
    let options = parse_comma_separated_component_values(function.value.clone(), |component_values| {
        rust_owned_image_set_option(component_values, filtered_input_string)
    })?;
    if options.is_empty() {
        return None;
    }

    Some(RustOwnedStyleValueKind::ImageSet(RustOwnedImageSet {
        options,
        source: serialize_component_values_for_reparsing(component_values, filtered_input_string)?,
    }))
}

fn rust_owned_image_set_option(
    component_values: Vec<ComponentValue>,
    filtered_input_string: &str,
) -> Option<RustOwnedImageSetOption> {
    let component_values = strip_whitespace(&component_values);
    if component_values.is_empty() {
        return None;
    }

    let mut parser = ComponentValueParser::new(component_values.to_vec());
    parser.discard_whitespace();

    let image = parser.next_component_value()?;
    let image_source = if component_value_parse_as_image_set_string(image)
        || component_value_parse_as_image_set_image(image)
        || component_value_parse_as_image_set_gradient(image)
    {
        let image_source =
            serialize_component_values_for_reparsing(std::slice::from_ref(image), filtered_input_string)?;
        parser.index += 1;
        image_source
    } else {
        return None;
    };

    let mut resolution = None;
    let mut mime_type = None;
    loop {
        parser.discard_whitespace();
        let Some(component_value) = parser.next_component_value() else {
            break;
        };

        if resolution.is_none() && component_value_parse_as_image_set_resolution(component_value) {
            resolution = Some(serialize_component_values_for_reparsing(
                std::slice::from_ref(component_value),
                filtered_input_string,
            )?);
            parser.index += 1;
            continue;
        }

        if mime_type.is_none()
            && let Some(value) = image_set_type_value(component_value)
        {
            mime_type = Some(value);
            parser.index += 1;
            continue;
        }

        return None;
    }

    Some(RustOwnedImageSetOption {
        image_source,
        resolution,
        mime_type,
    })
}

fn rust_owned_easing_function_style_value_kind(
    filtered_input: &[u8],
    filtered_input_string: &str,
) -> Option<RustOwnedStyleValueKind> {
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let component_values = strip_whitespace(&component_values);
    let source = serialize_component_values_for_reparsing(component_values, filtered_input_string)?;

    let value = match component_values {
        [
            ComponentValue::PreservedToken(Token {
                token_type: TokenType::Ident { value },
                ..
            }),
        ] if value.eq_ignore_ascii_case("step-start") || value.eq_ignore_ascii_case("step-end") => {
            RustOwnedEasingFunctionValue::Keyword(value.clone())
        }
        [ComponentValue::Function(function)] if function.name.eq_ignore_ascii_case("linear") => {
            RustOwnedEasingFunctionValue::Linear(rust_owned_linear_easing_stops(function, filtered_input_string)?)
        }
        [ComponentValue::Function(function)] if function.name.eq_ignore_ascii_case("cubic-bezier") => {
            let groups = rust_owned_single_component_function_arguments(function, filtered_input_string)?;
            let [x1, y1, x2, y2] = groups.as_slice() else {
                return None;
            };
            if !component_value_parse_as_number_in_range(x1, 0.0, 1.0)
                || !component_value_parse_as_number_prefix(y1)
                || !component_value_parse_as_number_in_range(x2, 0.0, 1.0)
                || !component_value_parse_as_number_prefix(y2)
            {
                return None;
            }
            RustOwnedEasingFunctionValue::CubicBezier {
                x1: serialize_component_values_for_reparsing(std::slice::from_ref(x1), filtered_input_string)?,
                y1: serialize_component_values_for_reparsing(std::slice::from_ref(y1), filtered_input_string)?,
                x2: serialize_component_values_for_reparsing(std::slice::from_ref(x2), filtered_input_string)?,
                y2: serialize_component_values_for_reparsing(std::slice::from_ref(y2), filtered_input_string)?,
            }
        }
        [ComponentValue::Function(function)] if function.name.eq_ignore_ascii_case("steps") => {
            let groups = rust_owned_single_component_function_arguments(function, filtered_input_string)?;
            if groups.is_empty() || groups.len() > 2 {
                return None;
            }

            let mut min_intervals = 1.0;
            let position = if let Some(step_position) = groups.get(1) {
                let ComponentValue::PreservedToken(Token {
                    token_type: TokenType::Ident { value },
                    ..
                }) = step_position
                else {
                    return None;
                };
                if !is_step_position_keyword(value) {
                    return None;
                }
                if value.eq_ignore_ascii_case("jump-none") {
                    min_intervals = 2.0;
                }
                Some(value.clone())
            } else {
                None
            };

            if !component_value_parse_as_integer_in_range(&groups[0], min_intervals, f64::INFINITY) {
                return None;
            }

            RustOwnedEasingFunctionValue::Steps {
                intervals: serialize_component_values_for_reparsing(
                    std::slice::from_ref(&groups[0]),
                    filtered_input_string,
                )?,
                position,
            }
        }
        _ => return None,
    };

    Some(RustOwnedStyleValueKind::EasingFunction(RustOwnedEasingFunction {
        value,
        source,
    }))
}

fn rust_owned_linear_easing_stops(
    function: &Function,
    filtered_input_string: &str,
) -> Option<Vec<RustOwnedLinearEasingStop>> {
    // https://drafts.csswg.org/css-easing-2/#typedef-linear-easing-function
    // <linear-easing-function> = linear( [ <number> && <linear-stop-length>? ]# )
    // <linear-stop-length> = <percentage>{1,2}
    let stops = parse_comma_separated_component_values(function.value.clone(), |component_values| {
        rust_owned_linear_easing_stop(component_values, filtered_input_string)
    })?;

    (!stops.is_empty()).then_some(stops)
}

fn rust_owned_linear_easing_stop(
    component_values: Vec<ComponentValue>,
    filtered_input_string: &str,
) -> Option<RustOwnedLinearEasingStop> {
    let component_values: Vec<_> = component_values
        .iter()
        .filter(|component_value| !is_whitespace_component_value(component_value))
        .cloned()
        .collect();
    let mut component_values = component_values.into_iter().peekable();

    let mut output = None;
    if component_values
        .peek()
        .is_some_and(component_value_parse_as_number_prefix)
    {
        output = Some(serialize_component_values_for_reparsing(
            std::slice::from_ref(&component_values.next()?),
            filtered_input_string,
        )?);
    }

    let mut stop_lengths = Vec::new();
    for _ in 0..2 {
        if component_values.peek().is_some_and(|component_value| {
            parse_percentage_value_prefix(component_value) == CssPrimitiveValueKind::Percentage
        }) {
            stop_lengths.push(serialize_component_values_for_reparsing(
                std::slice::from_ref(&component_values.next()?),
                filtered_input_string,
            )?);
        }
    }

    if component_values
        .peek()
        .is_some_and(component_value_parse_as_number_prefix)
    {
        if output.is_some() {
            return None;
        }
        output = Some(serialize_component_values_for_reparsing(
            std::slice::from_ref(&component_values.next()?),
            filtered_input_string,
        )?);
    }

    if component_values.next().is_some() {
        return None;
    }

    Some(RustOwnedLinearEasingStop {
        output: output?,
        first_stop_length: stop_lengths.first().cloned(),
        second_stop_length: stop_lengths.get(1).cloned(),
    })
}

fn rust_owned_single_component_function_arguments(
    function: &Function,
    filtered_input_string: &str,
) -> Option<Vec<ComponentValue>> {
    parse_comma_separated_component_values(function.value.clone(), |component_values| {
        let [component_value] = strip_whitespace(&component_values) else {
            return None;
        };
        serialize_component_values_for_reparsing(std::slice::from_ref(component_value), filtered_input_string)?;
        Some(component_value.clone())
    })
}

fn rust_owned_fit_content_style_value_kind(
    filtered_input: &[u8],
    filtered_input_string: &str,
) -> Option<RustOwnedStyleValueKind> {
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let component_values = strip_whitespace(&component_values);
    let source = serialize_component_values_for_reparsing(component_values, filtered_input_string)?;

    let value = match component_values {
        [
            ComponentValue::PreservedToken(Token {
                token_type: TokenType::Ident { value },
                ..
            }),
        ] if value.eq_ignore_ascii_case("fit-content") => RustOwnedFitContentValue::Keyword,
        [ComponentValue::Function(function)] if function.name.eq_ignore_ascii_case("fit-content") => {
            // https://drafts.csswg.org/css-sizing-3/#funcdef-width-fit-content
            // fit-content() = fit-content( <length-percentage [0,∞]> )
            let [component_value] = strip_whitespace(&function.value) else {
                return None;
            };
            if !component_value_parse_as_length_percentage(component_value) {
                return None;
            }
            RustOwnedFitContentValue::Function {
                argument: serialize_component_values_for_reparsing(
                    std::slice::from_ref(component_value),
                    filtered_input_string,
                )?,
            }
        }
        _ => return None,
    };

    Some(RustOwnedStyleValueKind::FitContent(RustOwnedFitContent {
        value,
        source,
    }))
}

fn rust_owned_rect_style_value_kind(
    filtered_input: &[u8],
    filtered_input_string: &str,
) -> Option<RustOwnedStyleValueKind> {
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let component_values = strip_whitespace(&component_values);
    let [ComponentValue::Function(function)] = component_values else {
        return None;
    };
    if !function.name.eq_ignore_ascii_case("rect") {
        return None;
    }

    // https://www.w3.org/TR/CSS2/visufx.html#value-def-shape
    // In CSS 2.1, the only valid <shape> value is:
    // rect(<top>, <right>, <bottom>, <left>)
    let mut parser = ComponentValueParser::new(function.value.clone());
    let mut sides = Vec::with_capacity(4);
    let mut requires_commas = None;

    for side in 0..4 {
        sides.push(rust_owned_rect_side(&mut parser, filtered_input_string)?);

        parser.discard_whitespace();
        if side == 3 {
            if parser.has_next_component_value() {
                return None;
            }
            break;
        }

        let next_is_comma = parser.consume_a_comma();
        match requires_commas {
            Some(true) if !next_is_comma => return None,
            Some(false) if next_is_comma => return None,
            None => requires_commas = Some(next_is_comma),
            _ => {}
        }
    }

    let [top, right, bottom, left] = sides.as_slice() else {
        return None;
    };

    Some(RustOwnedStyleValueKind::Rect(RustOwnedRect {
        top: top.clone(),
        right: right.clone(),
        bottom: bottom.clone(),
        left: left.clone(),
        requires_commas: requires_commas.unwrap_or(false),
        source: serialize_component_values_for_reparsing(component_values, filtered_input_string)?,
    }))
}

fn rust_owned_rect_side(parser: &mut ComponentValueParser, filtered_input_string: &str) -> Option<String> {
    parser.discard_whitespace();

    let component_value = parser.next_component_value()?;
    let is_auto = matches!(
        component_value,
        ComponentValue::PreservedToken(Token {
            token_type: TokenType::Ident { value },
            ..
        }) if value.eq_ignore_ascii_case("auto")
    );
    if is_auto || component_value_parse_as_length(component_value) {
        let value =
            serialize_component_values_for_reparsing(std::slice::from_ref(component_value), filtered_input_string)?;
        parser.index += 1;
        return Some(value);
    }

    None
}

fn rust_owned_primitive_style_value_kind(
    value_type: PropertyValueType,
    primitive_kind: CssPrimitiveValueKind,
    numeric_value: Option<f64>,
    secondary_numeric_value: Option<f64>,
    value: String,
) -> RustOwnedStyleValueKind {
    if numeric_value.is_none()
        && matches!(
            primitive_kind,
            CssPrimitiveValueKind::Integer
                | CssPrimitiveValueKind::Number
                | CssPrimitiveValueKind::Percentage
                | CssPrimitiveValueKind::Length
                | CssPrimitiveValueKind::Time
                | CssPrimitiveValueKind::Ratio
        )
    {
        return RustOwnedStyleValueKind::Primitive {
            primitive_kind,
            numeric_value,
            secondary_numeric_value,
            value,
            value_type,
        };
    }

    match primitive_kind {
        CssPrimitiveValueKind::Integer => RustOwnedStyleValueKind::Integer {
            value: numeric_value.unwrap_or(0.0) as i32,
            value_type,
        },
        CssPrimitiveValueKind::Number if value_type == PropertyValueType::OpacityValue => {
            RustOwnedStyleValueKind::OpacityValue {
                primitive_kind,
                value: numeric_value.unwrap_or(0.0),
            }
        }
        CssPrimitiveValueKind::Number => RustOwnedStyleValueKind::Number {
            value: numeric_value.unwrap_or(0.0),
            value_type,
        },
        CssPrimitiveValueKind::Percentage if value_type == PropertyValueType::OpacityValue => {
            RustOwnedStyleValueKind::OpacityValue {
                primitive_kind,
                value: numeric_value.unwrap_or(0.0),
            }
        }
        CssPrimitiveValueKind::Percentage => RustOwnedStyleValueKind::Percentage {
            value: numeric_value.unwrap_or(0.0),
            value_type,
        },
        CssPrimitiveValueKind::Length => RustOwnedStyleValueKind::Length(RustOwnedDimensionStyleValue {
            value: numeric_value.unwrap_or(0.0),
            unit: value,
            value_type,
        }),
        CssPrimitiveValueKind::Time => RustOwnedStyleValueKind::Time(RustOwnedDimensionStyleValue {
            value: numeric_value.unwrap_or(0.0),
            unit: value,
            value_type,
        }),
        CssPrimitiveValueKind::Ratio => RustOwnedStyleValueKind::Ratio {
            numerator: numeric_value.unwrap_or(0.0),
            denominator: secondary_numeric_value.unwrap_or(1.0),
            has_denominator: value == "has-denominator",
            value_type,
        },
        CssPrimitiveValueKind::String => RustOwnedStyleValueKind::String { value, value_type },
        _ => RustOwnedStyleValueKind::Primitive {
            primitive_kind,
            numeric_value,
            secondary_numeric_value,
            value,
            value_type,
        },
    }
}

fn parse_rust_owned_math_function(
    component_values: &[ComponentValue],
    filtered_input: &[u8],
) -> Option<RustOwnedMathFunction> {
    // https://drafts.csswg.org/css-values-4/#math
    // A math function represents a numeric value.
    let [ComponentValue::Function(function)] = component_values else {
        return None;
    };
    if !is_math_function_name(&function.name) {
        return None;
    }

    let filtered_input = std::str::from_utf8(filtered_input)
        .expect("rust_css_parse_component_values received non-UTF-8 input after C++ decoding");
    let source = serialize_component_values_for_reparsing(component_values, filtered_input)?;
    let arguments = serialize_math_function_arguments_for_reparsing(&function.value, filtered_input)?;

    Some(RustOwnedMathFunction {
        name: function.name.clone(),
        arguments,
        source,
    })
}

fn serialize_math_function_arguments_for_reparsing(
    component_values: &[ComponentValue],
    filtered_input: &str,
) -> Option<Vec<String>> {
    let mut arguments = Vec::new();
    let mut start = 0;

    for (index, component_value) in component_values.iter().enumerate() {
        if !matches!(
            component_value,
            ComponentValue::PreservedToken(Token {
                token_type: TokenType::Comma,
                ..
            })
        ) {
            continue;
        }

        arguments.push(serialize_component_values_for_reparsing(
            strip_whitespace(&component_values[start..index]),
            filtered_input,
        )?);
        start = index + 1;
    }

    arguments.push(serialize_component_values_for_reparsing(
        strip_whitespace(&component_values[start..]),
        filtered_input,
    )?);
    Some(arguments)
}

fn filtered_input_to_string(filtered_input: &[u8]) -> String {
    String::from_utf8_lossy(filtered_input).to_string()
}

fn split_component_values_on_comma(component_values: &[ComponentValue]) -> Vec<&[ComponentValue]> {
    let mut groups = Vec::new();
    let mut start = 0;
    for (index, component_value) in component_values.iter().enumerate() {
        if matches!(
            component_value,
            ComponentValue::PreservedToken(Token {
                token_type: TokenType::Comma,
                ..
            })
        ) {
            groups.push(&component_values[start..index]);
            start = index + 1;
        }
    }
    groups.push(&component_values[start..]);
    groups
}

pub(crate) fn parse_style_value_for_property<C>(property_ids: &[u16], filtered_input: &[u8], mut callback: C) -> bool
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    let RustOwnedStyleValueParseResult::Parsed(style_value) =
        parse_rust_owned_style_value_for_property(property_ids, filtered_input)
    else {
        return false;
    };

    emit_rust_owned_style_value(&style_value, &mut callback);
    true
}

fn emit_rust_owned_style_value<C>(style_value: &RustOwnedStyleValue, callback: &mut C)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    let property_id = style_value.property_id as u16;
    match &style_value.value {
        RustOwnedStyleValueKind::Image(_) => {
            callback_style_value_type(
                callback,
                CssStyleValueKind::ValueType,
                property_id,
                PropertyValueType::Image,
            );
        }
        RustOwnedStyleValueKind::Anchor(_) => {
            callback_style_value_type(
                callback,
                CssStyleValueKind::ValueType,
                property_id,
                PropertyValueType::Anchor,
            );
        }
        RustOwnedStyleValueKind::Counter(_) => {
            callback_style_value_type(
                callback,
                CssStyleValueKind::ValueType,
                property_id,
                PropertyValueType::Counter,
            );
        }
        RustOwnedStyleValueKind::ImageSet(_) => {
            callback_style_value_type(
                callback,
                CssStyleValueKind::ValueType,
                property_id,
                PropertyValueType::Image,
            );
        }
        RustOwnedStyleValueKind::FontStyle(value) => callback(
            CssStyleValueKind::FontStyle,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            css_font_style_kind(value.value) as u8,
            u8::from(value.angle.is_some()),
            0,
            0,
            value.angle.as_ref().map_or(&[], |angle| angle.as_bytes()),
            property_value_type_name(PropertyValueType::FontStyle),
        ),
        RustOwnedStyleValueKind::AnchorNameOrScope(value) => {
            let name_bytes = null_separated_string_list_bytes(&value.names);
            callback(
                CssStyleValueKind::AnchorNameOrScope,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &name_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::AnimationName(value) => {
            let name_bytes = null_terminated_animation_name_item_bytes(&value.names);
            callback(
                CssStyleValueKind::AnimationName,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &name_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::AspectRatio(value) => {
            if value.numerator_source.is_none() {
                callback(
                    CssStyleValueKind::AspectRatio,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    2,
                    value.has_auto as u8,
                    0,
                    0,
                    &[],
                    "",
                );
            }
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::AspectRatio,
                property_id,
                0,
                value.numerator_source.as_ref(),
            );
            if value.has_auto && value.numerator_source.is_some() {
                callback(
                    CssStyleValueKind::AspectRatio,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    2,
                    1,
                    0,
                    0,
                    &[],
                    "",
                );
            }
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::AspectRatio,
                property_id,
                1,
                value.denominator_source.as_ref(),
            );
        }
        RustOwnedStyleValueKind::BackgroundSize(_) => callback(
            CssStyleValueKind::Invalid,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::BorderRadius(value) => {
            for source in &value.horizontal_sources {
                callback_optional_longhand_source(
                    callback,
                    CssStyleValueKind::BorderRadius,
                    property_id,
                    0,
                    Some(source),
                );
            }
            for source in &value.vertical_sources {
                callback_optional_longhand_source(
                    callback,
                    CssStyleValueKind::BorderRadius,
                    property_id,
                    1,
                    Some(source),
                );
            }
        }
        RustOwnedStyleValueKind::Columns(value) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Columns,
                property_id,
                0,
                value.column_count_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Columns,
                property_id,
                1,
                value.column_width_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Columns,
                property_id,
                2,
                value.column_height_source.as_ref(),
            );
        }
        RustOwnedStyleValueKind::Content { source } => {
            callback_source_backed_style_value(callback, CssStyleValueKind::Content, property_id, source);
        }
        RustOwnedStyleValueKind::ColorScheme(value) => {
            let scheme_bytes = null_separated_string_list_bytes(&value.schemes);
            callback(
                CssStyleValueKind::ColorScheme,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.value.kind as u8,
                u8::from(value.value.only),
                0,
                0,
                &scheme_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::Contain(value) => callback(
            CssStyleValueKind::Contain,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.kind as u8,
            (value.value.is_size as u8)
                | ((value.value.is_inline_size as u8) << 1)
                | ((value.value.has_layout as u8) << 2)
                | ((value.value.has_style as u8) << 3)
                | ((value.value.has_paint as u8) << 4),
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::ContainerType(value) => callback(
            CssStyleValueKind::ContainerType,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value as u8,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::CounterDefinitions(value) => {
            for definition in &value.definitions {
                callback(
                    CssStyleValueKind::CounterDefinitions,
                    property_id,
                    CssPrimitiveValueKind::Integer,
                    true,
                    f64::from(definition.value),
                    false,
                    0.0,
                    u8::from(definition.is_reversed),
                    0,
                    0,
                    0,
                    definition.name.as_bytes(),
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::Cursor(value) => callback_cursor_style_value(callback, property_id, value),
        RustOwnedStyleValueKind::Display(value) => callback(
            CssStyleValueKind::Display,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.kind as u8,
            match value.kind {
                CssDisplayValueKind::Box => value.box_ as u8,
                CssDisplayValueKind::Internal => value.internal as u8,
                CssDisplayValueKind::OutsideAndInside => value.outside as u8,
                CssDisplayValueKind::Invalid => 0,
            },
            value.inside as u8,
            value.list_item as u8,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::FlexShorthand(RustOwnedFlexShorthand::None) => callback(
            CssStyleValueKind::Flex,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::FlexShorthand(RustOwnedFlexShorthand::Longhands {
            flex_grow_source,
            flex_shrink_source,
            flex_basis_source,
        }) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Flex,
                property_id,
                1,
                Some(flex_grow_source),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Flex,
                property_id,
                2,
                Some(flex_shrink_source),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::Flex,
                property_id,
                3,
                Some(flex_basis_source),
            );
        }
        RustOwnedStyleValueKind::FlexFlow(value) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::FlexFlow,
                property_id,
                0,
                value.flex_direction_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::FlexFlow,
                property_id,
                1,
                value.flex_wrap_source.as_ref(),
            );
        }
        RustOwnedStyleValueKind::FilterValueList { value } => {
            callback_filter_value_list_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::GridAutoFlow(value) => callback(
            CssStyleValueKind::GridAutoFlow,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.axis as u8,
            value.dense as u8,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::GridAutoTrackSizes(value) => {
            callback_grid_track_size_list_style_value(
                callback,
                CssStyleValueKind::GridAutoTrackSizes,
                property_id,
                value,
            );
        }
        RustOwnedStyleValueKind::GridTrackPlacement(value) => {
            callback_grid_track_placement_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::GridTrackSizeList(value) => {
            callback_grid_track_size_list_style_value(
                callback,
                CssStyleValueKind::GridTrackSizeList,
                property_id,
                value,
            );
        }
        RustOwnedStyleValueKind::ListStyle(value) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::ListStyle,
                property_id,
                0,
                value.position_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::ListStyle,
                property_id,
                1,
                value.image_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::ListStyle,
                property_id,
                2,
                value.type_source.as_ref(),
            );
        }
        RustOwnedStyleValueKind::MathDepth(value) => match value {
            RustOwnedMathDepth::AutoAdd => callback(
                CssStyleValueKind::MathDepth,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                0,
                0,
                0,
                0,
                &[],
                "",
            ),
            RustOwnedMathDepth::Add { integer_source } => callback(
                CssStyleValueKind::MathDepth,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                1,
                0,
                0,
                0,
                integer_source.as_bytes(),
                "",
            ),
            RustOwnedMathDepth::Integer { integer_source } => callback(
                CssStyleValueKind::MathDepth,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                2,
                0,
                0,
                0,
                integer_source.as_bytes(),
                "",
            ),
        },
        RustOwnedStyleValueKind::PaintOrder(value) => callback(
            CssStyleValueKind::PaintOrder,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.kind as u8,
            value.value.first as u8,
            value.value.second as u8,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::PlaceContent(value) => {
            callback_place_shorthand_style_value(callback, CssStyleValueKind::PlaceContent, property_id, value);
        }
        RustOwnedStyleValueKind::PlaceItems(value) => {
            callback_place_shorthand_style_value(callback, CssStyleValueKind::PlaceItems, property_id, value);
        }
        RustOwnedStyleValueKind::PlaceSelf(value) => {
            callback_place_shorthand_style_value(callback, CssStyleValueKind::PlaceSelf, property_id, value);
        }
        RustOwnedStyleValueKind::PositionAnchor(value) => callback(
            CssStyleValueKind::PositionAnchor,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.kind as u8,
            0,
            0,
            0,
            value.name.as_ref().map_or(&[], |name| name.as_bytes()),
            "",
        ),
        RustOwnedStyleValueKind::PositionArea(value) => {
            callback_position_area_style_value(callback, CssStyleValueKind::PositionArea, property_id, value);
        }
        RustOwnedStyleValueKind::Position(value) => {
            callback_style_value_type(callback, CssStyleValueKind::ValueType, property_id, value.value_type);
        }
        RustOwnedStyleValueKind::PositionTryFallbacks(value) => {
            callback_position_try_fallbacks_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::PositionTryOrder(value) => callback(
            CssStyleValueKind::PositionTryOrder,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value as u8,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::PositionVisibility(value) => callback(
            CssStyleValueKind::PositionVisibility,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.kind as u8,
            (value.value.has_anchors_valid as u8)
                | ((value.value.has_anchors_visible as u8) << 1)
                | ((value.value.has_no_overflow as u8) << 2),
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::Quotes(value) => {
            let string_bytes = null_separated_string_list_bytes(&value.strings);
            callback(
                CssStyleValueKind::Quotes,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &string_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::RepeatStyle(value) => callback(
            CssStyleValueKind::RepeatStyle,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.repeat_x as u8,
            value.repeat_y as u8,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::OverflowClipMargin { length_source } => {
            callback_source_backed_style_value(
                callback,
                CssStyleValueKind::OverflowClipMargin,
                property_id,
                length_source,
            );
        }
        RustOwnedStyleValueKind::ScrollbarColor(value) => callback(
            CssStyleValueKind::ScrollbarColor,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            match value {
                RustOwnedScrollbarColor::Auto { .. } => 1,
                RustOwnedScrollbarColor::Colors { .. } => 2,
            },
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::ScrollbarGutter(value) => callback(
            CssStyleValueKind::ScrollbarGutter,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value as u8,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::Shadow(value) => {
            callback_shadow_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::ShapeOutside { source } => {
            callback_source_backed_style_value(callback, CssStyleValueKind::ShapeOutside, property_id, source);
        }
        RustOwnedStyleValueKind::TextDecoration(value) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TextDecoration,
                property_id,
                0,
                value.line_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TextDecoration,
                property_id,
                1,
                value.thickness_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TextDecoration,
                property_id,
                2,
                value.style_source.as_ref(),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TextDecoration,
                property_id,
                3,
                value.color_source.as_ref(),
            );
        }
        RustOwnedStyleValueKind::TextDecorationLine(value) => callback(
            CssStyleValueKind::TextDecorationLine,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.bits,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TimelineName(value) => {
            let name_bytes = null_terminated_timeline_name_item_bytes(&value.names);
            callback(
                CssStyleValueKind::TimelineName,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &name_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::TimelineScope(value) => {
            let name_bytes = null_separated_string_list_bytes(&value.names);
            callback(
                CssStyleValueKind::TimelineScope,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &name_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::TextWrap(value) => callback(
            CssStyleValueKind::TextWrap,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.mode as u8,
            value.value.style as u8,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TextWrapMode(value) => callback(
            CssStyleValueKind::TextWrapMode,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value as u8,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TextWrapStyle(value) => callback(
            CssStyleValueKind::TextWrapStyle,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value as u8,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TextIndent(value) => callback(
            CssStyleValueKind::TextIndent,
            property_id,
            value.length_percentage.primitive_kind,
            value.length_percentage.numeric_value.is_some(),
            value.length_percentage.numeric_value.unwrap_or(0.0),
            false,
            0.0,
            u8::from(value.has_hanging),
            u8::from(value.has_each_line),
            0,
            0,
            value.length_percentage.unit.as_bytes(),
            property_value_type_name(value.length_percentage.value_type),
        ),
        RustOwnedStyleValueKind::TextUnderlinePosition(value) => callback(
            CssStyleValueKind::TextUnderlinePosition,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.horizontal as u8,
            value.value.vertical as u8,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TransformOrigin(value) => {
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TransformOrigin,
                property_id,
                0,
                Some(&value.x_source),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TransformOrigin,
                property_id,
                1,
                Some(&value.y_source),
            );
            callback_optional_longhand_source(
                callback,
                CssStyleValueKind::TransformOrigin,
                property_id,
                2,
                Some(&value.z_source),
            );
        }
        RustOwnedStyleValueKind::TransformLonghand(value) => {
            callback_transform_longhand_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::Transformation(_) => {}
        RustOwnedStyleValueKind::TouchAction(value) => callback(
            CssStyleValueKind::TouchAction,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.kind as u8,
            value.value.first as u8,
            value.value.second as u8,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::TransitionBehavior(value) => {
            let behavior_bytes = value
                .behaviors
                .iter()
                .map(|behavior| *behavior as u8)
                .collect::<Vec<_>>();
            callback(
                CssStyleValueKind::TransitionBehavior,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &behavior_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::TransitionProperty(value) => {
            let mut property_bytes = Vec::new();
            for (index, property) in value.properties.iter().enumerate() {
                if index > 0 {
                    property_bytes.push(0);
                }
                property_bytes.extend_from_slice(property.as_bytes());
            }
            callback(
                CssStyleValueKind::TransitionProperty,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &property_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::ViewTransitionName(value) => callback(
            CssStyleValueKind::ViewTransitionName,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.kind as u8,
            0,
            0,
            0,
            value.name.as_ref().map_or(&[], |name| name.as_bytes()),
            "",
        ),
        RustOwnedStyleValueKind::WhiteSpaceTrim(value) => callback(
            CssStyleValueKind::WhiteSpaceTrim,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.value.kind as u8,
            (value.value.has_discard_before as u8)
                | ((value.value.has_discard_after as u8) << 1)
                | ((value.value.has_discard_inner as u8) << 2),
            0,
            0,
            &[],
            "",
        ),
        RustOwnedStyleValueKind::WillChange(value) => {
            let feature_bytes = null_terminated_will_change_feature_bytes(&value.features);
            callback(
                CssStyleValueKind::WillChange,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                value.kind as u8,
                0,
                0,
                0,
                &feature_bytes,
                "",
            );
        }
        RustOwnedStyleValueKind::Angle(value)
        | RustOwnedStyleValueKind::Flex(value)
        | RustOwnedStyleValueKind::Frequency(value)
        | RustOwnedStyleValueKind::Resolution(value) => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Invalid,
            Some(value.value),
            None,
            value.unit.as_bytes(),
            value.value_type,
        ),
        RustOwnedStyleValueKind::Integer { value, value_type } => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Integer,
            Some(*value as f64),
            None,
            &[],
            *value_type,
        ),
        RustOwnedStyleValueKind::Length(value) => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Length,
            Some(value.value),
            None,
            value.unit.as_bytes(),
            value.value_type,
        ),
        RustOwnedStyleValueKind::Number { value, value_type } => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Number,
            Some(*value),
            None,
            &[],
            *value_type,
        ),
        RustOwnedStyleValueKind::OpacityValue { primitive_kind, value } => callback_primitive_style_value(
            callback,
            property_id,
            *primitive_kind,
            Some(*value),
            None,
            &[],
            PropertyValueType::OpacityValue,
        ),
        RustOwnedStyleValueKind::Percentage { value, value_type } => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Percentage,
            Some(*value),
            None,
            &[],
            *value_type,
        ),
        RustOwnedStyleValueKind::Ratio {
            numerator,
            denominator,
            has_denominator,
            value_type,
        } => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Ratio,
            Some(*numerator),
            Some(*denominator),
            if *has_denominator { b"has-denominator" } else { b"" },
            *value_type,
        ),
        RustOwnedStyleValueKind::String { value, value_type } => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::String,
            None,
            None,
            value.as_bytes(),
            *value_type,
        ),
        RustOwnedStyleValueKind::StrokeDasharray(value) => match value {
            RustOwnedStrokeDasharray::None => callback(
                CssStyleValueKind::StrokeDasharray,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                1,
                0,
                0,
                0,
                &[],
                "",
            ),
            RustOwnedStrokeDasharray::Values(values) => {
                for value in values {
                    callback(
                        CssStyleValueKind::StrokeDasharray,
                        property_id,
                        CssPrimitiveValueKind::Invalid,
                        false,
                        0.0,
                        false,
                        0.0,
                        0,
                        0,
                        0,
                        0,
                        value.as_bytes(),
                        "",
                    );
                }
            }
        },
        RustOwnedStyleValueKind::Time(value) => callback_primitive_style_value(
            callback,
            property_id,
            CssPrimitiveValueKind::Time,
            Some(value.value),
            None,
            value.unit.as_bytes(),
            value.value_type,
        ),
        RustOwnedStyleValueKind::Calculated(function) => {
            let _ = function;
            callback_style_value_type(
                callback,
                CssStyleValueKind::ValueType,
                property_id,
                PropertyValueType::Number,
            );
        }
        RustOwnedStyleValueKind::Function(function) | RustOwnedStyleValueKind::TreeCountingFunction(function) => {
            let _ = function;
        }
        RustOwnedStyleValueKind::CounterStyle { .. } => callback_style_value_type(
            callback,
            CssStyleValueKind::ValueType,
            property_id,
            PropertyValueType::CounterStyle,
        ),
        RustOwnedStyleValueKind::FontVariantAlternates { values } => {
            for value in values {
                let feature_value_names = null_separated_string_list_bytes(&value.feature_value_names);
                callback(
                    CssStyleValueKind::FontVariantAlternates,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    value.kind as u8,
                    0,
                    0,
                    0,
                    &feature_value_names,
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::FontVariantEastAsian { values } => {
            for value in values {
                callback(
                    CssStyleValueKind::FontVariantEastAsian,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    value.kind as u8,
                    0,
                    0,
                    0,
                    value.value.as_bytes(),
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::FontVariantLigatures { values } => {
            for value in values {
                callback(
                    CssStyleValueKind::FontVariantLigatures,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    value.kind as u8,
                    0,
                    0,
                    0,
                    value.value.as_bytes(),
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::FontVariantNumeric { values } => {
            for value in values {
                callback(
                    CssStyleValueKind::FontVariantNumeric,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    value.kind as u8,
                    0,
                    0,
                    0,
                    value.value.as_bytes(),
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::Shorthand(value_list)
        | RustOwnedStyleValueKind::Tuple(value_list)
        | RustOwnedStyleValueKind::ValueList(value_list) => {
            if let Some(value_type) = value_list.value_type {
                callback_style_value_type(callback, CssStyleValueKind::ValueType, property_id, value_type);
            }
        }
        RustOwnedStyleValueKind::GuaranteedInvalid => {}
        RustOwnedStyleValueKind::Keyword(value) => callback(
            CssStyleValueKind::Keyword,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            value.as_bytes(),
            "",
        ),
        RustOwnedStyleValueKind::CustomIdent { value, value_type } => callback(
            CssStyleValueKind::CustomIdent,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            value.as_bytes(),
            property_value_type_name(*value_type),
        ),
        RustOwnedStyleValueKind::Primitive {
            primitive_kind,
            numeric_value,
            secondary_numeric_value,
            value,
            value_type,
        } => callback(
            CssStyleValueKind::Primitive,
            property_id,
            *primitive_kind,
            numeric_value.is_some(),
            numeric_value.unwrap_or(0.0),
            secondary_numeric_value.is_some(),
            secondary_numeric_value.unwrap_or(0.0),
            0,
            0,
            0,
            0,
            value.as_bytes(),
            property_value_type_name(*value_type),
        ),
        RustOwnedStyleValueKind::Color {
            red,
            green,
            blue,
            alpha,
            name,
        } => callback(
            CssStyleValueKind::Color,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            *red,
            *green,
            *blue,
            *alpha,
            name.as_deref().unwrap_or("").as_bytes(),
            "",
        ),
        RustOwnedStyleValueKind::Url(value) => callback(
            CssStyleValueKind::Url,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            value.as_bytes(),
            property_value_type_name(PropertyValueType::Url),
        ),
        RustOwnedStyleValueKind::CounterStyleName(value) => callback(
            CssStyleValueKind::CounterStyleName,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            value.as_bytes(),
            property_value_type_name(PropertyValueType::CounterStyle),
        ),
        RustOwnedStyleValueKind::EasingFunction(_) => callback_style_value_type(
            callback,
            CssStyleValueKind::EasingFunction,
            property_id,
            PropertyValueType::EasingFunction,
        ),
        RustOwnedStyleValueKind::FitContent(_) => callback_style_value_type(
            callback,
            CssStyleValueKind::FitContent,
            property_id,
            PropertyValueType::FitContent,
        ),
        RustOwnedStyleValueKind::FontFamily { values } => {
            for value in values {
                let (kind, family_name, is_string) = match value {
                    FontFamilyValue::Generic(value) => (CssFontFamilyValueKind::Generic, value, false),
                    FontFamilyValue::FamilyName(value) => {
                        (CssFontFamilyValueKind::FamilyName, &value.name, value.is_string)
                    }
                };
                callback(
                    CssStyleValueKind::FontFamily,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    kind as u8,
                    u8::from(is_string),
                    0,
                    0,
                    family_name.as_bytes(),
                    "",
                );
            }
        }
        RustOwnedStyleValueKind::FontFeatureSettings { value } => {
            callback_open_type_settings_style_value(
                callback,
                CssStyleValueKind::FontFeatureSettings,
                property_id,
                value,
            );
        }
        RustOwnedStyleValueKind::FontLanguageOverride { kind, value } => callback(
            CssStyleValueKind::FontLanguageOverride,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            *kind as u8,
            0,
            0,
            0,
            value.as_ref().map_or(&[], |value| value.as_bytes()),
            "",
        ),
        RustOwnedStyleValueKind::FontVariant { value } => {
            callback_font_variant_style_value(callback, property_id, value);
        }
        RustOwnedStyleValueKind::FontVariationSettings { value } => {
            callback_open_type_settings_style_value(
                callback,
                CssStyleValueKind::FontVariationSettings,
                property_id,
                value,
            );
        }
        RustOwnedStyleValueKind::BasicShape(_) => callback_style_value_type(
            callback,
            CssStyleValueKind::BasicShape,
            property_id,
            PropertyValueType::BasicShape,
        ),
        RustOwnedStyleValueKind::Rect(_) => {
            callback_style_value_type(callback, CssStyleValueKind::Rect, property_id, PropertyValueType::Rect);
        }
        RustOwnedStyleValueKind::ScrollFunction { scroller, axis } => callback(
            CssStyleValueKind::ScrollFunction,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            *scroller as u8,
            *axis as u8,
            0,
            0,
            &[],
            property_value_type_name(PropertyValueType::ScrollFunction),
        ),
        RustOwnedStyleValueKind::ViewTimelineInset { count } => callback(
            CssStyleValueKind::ViewTimelineInset,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            *count as u8,
            0,
            0,
            0,
            &[],
            property_value_type_name(PropertyValueType::ViewTimelineInset),
        ),
        RustOwnedStyleValueKind::ViewFunction {
            axis,
            inset,
            inset_position,
        } => callback(
            CssStyleValueKind::ViewFunction,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            *axis as u8,
            *inset as u8,
            *inset_position as u8,
            0,
            &[],
            property_value_type_name(PropertyValueType::ViewFunction),
        ),
        RustOwnedStyleValueKind::MathFunction { value_type, .. } => {
            callback_style_value_type(callback, CssStyleValueKind::ValueType, property_id, *value_type);
        }
        RustOwnedStyleValueKind::UnresolvedValueType { value_type, .. } => {
            callback_style_value_type(callback, CssStyleValueKind::ValueType, property_id, *value_type);
        }
    }
}

fn callback_primitive_style_value<C>(
    callback: &mut C,
    property_id: u16,
    primitive_kind: CssPrimitiveValueKind,
    numeric_value: Option<f64>,
    secondary_numeric_value: Option<f64>,
    value: &[u8],
    value_type: PropertyValueType,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        CssStyleValueKind::Primitive,
        property_id,
        primitive_kind,
        numeric_value.is_some(),
        numeric_value.unwrap_or(0.0),
        secondary_numeric_value.is_some(),
        secondary_numeric_value.unwrap_or(0.0),
        0,
        0,
        0,
        0,
        value,
        property_value_type_name(value_type),
    );
}

fn callback_style_value_type<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    value_type: PropertyValueType,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        kind,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        0,
        0,
        0,
        0,
        &[],
        property_value_type_name(value_type),
    );
}

fn callback_open_type_settings_style_value<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    value: &RustOwnedOpenTypeSettings,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        kind,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        value.kind as u8,
        0,
        0,
        0,
        &[],
        "",
    );

    for tag_value in &value.tag_values {
        let mut tag_and_value = tag_value.tag.as_bytes().to_vec();
        if let Some(value) = &tag_value.value {
            tag_and_value.extend_from_slice(value.as_bytes());
        }
        callback(
            kind,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            value.kind as u8,
            tag_value.value_kind as u8,
            0,
            0,
            &tag_and_value,
            "",
        );
    }
}

fn css_font_style_kind(value: FontStyle) -> CssFontStyleKind {
    match value {
        FontStyle::Normal => CssFontStyleKind::Normal,
        FontStyle::Italic => CssFontStyleKind::Italic,
        FontStyle::Left => CssFontStyleKind::Left,
        FontStyle::Right => CssFontStyleKind::Right,
        FontStyle::Oblique { .. } => CssFontStyleKind::Oblique,
    }
}

fn callback_source_backed_style_value<C>(callback: &mut C, kind: CssStyleValueKind, property_id: u16, source: &str)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        kind,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        0,
        0,
        0,
        0,
        source.as_bytes(),
        "",
    );
}

fn callback_optional_longhand_source<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    index: u8,
    source: Option<&String>,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    if let Some(source) = source {
        callback(
            kind,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            index,
            0,
            0,
            0,
            source.as_bytes(),
            "",
        );
    }
}

const GRID_TRACK_SIZE_LIST_CALLBACK_NONE: u8 = 0;
const GRID_TRACK_SIZE_LIST_CALLBACK_LINE_NAMES: u8 = 1;
const GRID_TRACK_SIZE_LIST_CALLBACK_BREADTH: u8 = 2;
const GRID_TRACK_SIZE_LIST_CALLBACK_MINMAX: u8 = 3;
const GRID_TRACK_SIZE_LIST_CALLBACK_FIT_CONTENT: u8 = 4;
const GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_BEGIN: u8 = 5;
const GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_END: u8 = 6;
const GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_AUTO_FILL: u8 = 0;
const GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_AUTO_FIT: u8 = 1;
const GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_FIXED: u8 = 2;

fn callback_grid_track_size_list_style_value<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    value: &RustOwnedGridTrackSizeList,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match value {
        RustOwnedGridTrackSizeList::None => callback(
            kind,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            GRID_TRACK_SIZE_LIST_CALLBACK_NONE,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedGridTrackSizeList::List(items) => {
            callback_grid_track_size_list_items(callback, kind, property_id, items);
        }
    }
}

fn callback_grid_track_size_list_items<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    items: &[RustOwnedGridTrackSizeListItem],
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    for item in items {
        match item {
            RustOwnedGridTrackSizeListItem::LineNames(names) => {
                let names = null_separated_string_list_bytes(names);
                callback(
                    kind,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    GRID_TRACK_SIZE_LIST_CALLBACK_LINE_NAMES,
                    0,
                    0,
                    0,
                    &names,
                    "",
                );
            }
            RustOwnedGridTrackSizeListItem::Track(track) => {
                callback_explicit_grid_track(callback, kind, property_id, track);
            }
        }
    }
}

fn callback_explicit_grid_track<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    track: &RustOwnedExplicitGridTrack,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match track {
        RustOwnedExplicitGridTrack::Size(size) => match size {
            RustOwnedGridTrackSize::Breadth(source) => callback(
                kind,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                GRID_TRACK_SIZE_LIST_CALLBACK_BREADTH,
                0,
                0,
                0,
                source.as_bytes(),
                "",
            ),
            RustOwnedGridTrackSize::MinMax { min_source, max_source } => callback(
                kind,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                GRID_TRACK_SIZE_LIST_CALLBACK_MINMAX,
                0,
                0,
                0,
                min_source.as_bytes(),
                max_source,
            ),
            RustOwnedGridTrackSize::FitContent(source) => callback(
                kind,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                GRID_TRACK_SIZE_LIST_CALLBACK_FIT_CONTENT,
                0,
                0,
                0,
                source.as_bytes(),
                "",
            ),
        },
        RustOwnedExplicitGridTrack::Repeat(repeat) => {
            let (repeat_type, count_source) = match &repeat.repeat_type {
                RustOwnedGridRepeatType::AutoFill => (GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_AUTO_FILL, None),
                RustOwnedGridRepeatType::AutoFit => (GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_AUTO_FIT, None),
                RustOwnedGridRepeatType::Fixed { count_source } => {
                    (GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_FIXED, Some(count_source.as_str()))
                }
            };

            callback(
                kind,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_BEGIN,
                repeat_type,
                0,
                0,
                count_source.unwrap_or("").as_bytes(),
                "",
            );
            callback_grid_track_size_list_items(callback, kind, property_id, &repeat.track_list);
            callback(
                kind,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                GRID_TRACK_SIZE_LIST_CALLBACK_REPEAT_END,
                0,
                0,
                0,
                &[],
                "",
            );
        }
    }
}

const GRID_TRACK_PLACEMENT_CALLBACK_AUTO: u8 = 0;
const GRID_TRACK_PLACEMENT_CALLBACK_LINE: u8 = 1;
const GRID_TRACK_PLACEMENT_CALLBACK_SPAN: u8 = 2;

fn callback_grid_track_placement_style_value<C>(callback: &mut C, property_id: u16, value: &RustOwnedGridTrackPlacement)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    let (kind, line_number_source, name) = match value {
        RustOwnedGridTrackPlacement::Auto => (GRID_TRACK_PLACEMENT_CALLBACK_AUTO, None, None),
        RustOwnedGridTrackPlacement::Line {
            line_number_source,
            name,
        } => (
            GRID_TRACK_PLACEMENT_CALLBACK_LINE,
            line_number_source.as_deref(),
            name.as_deref(),
        ),
        RustOwnedGridTrackPlacement::Span {
            line_number_source,
            name,
        } => (
            GRID_TRACK_PLACEMENT_CALLBACK_SPAN,
            line_number_source.as_deref(),
            name.as_deref(),
        ),
    };

    callback(
        CssStyleValueKind::GridTrackPlacement,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        kind,
        0,
        0,
        0,
        line_number_source.unwrap_or("").as_bytes(),
        name.unwrap_or(""),
    );
}

const CURSOR_CALLBACK_IMAGE: u8 = 0;
const CURSOR_CALLBACK_PREDEFINED: u8 = 1;
const FILTER_VALUE_LIST_CALLBACK_NONE: u8 = 0;
const FILTER_VALUE_LIST_CALLBACK_URL: u8 = 1;
const FILTER_VALUE_LIST_CALLBACK_BLUR: u8 = 2;
const FILTER_VALUE_LIST_CALLBACK_DROP_SHADOW: u8 = 3;
const FILTER_VALUE_LIST_CALLBACK_HUE_ROTATE: u8 = 4;
const FILTER_VALUE_LIST_CALLBACK_SIMPLE: u8 = 5;

const SIMPLE_FILTER_FUNCTION_BRIGHTNESS: u8 = 0;
const SIMPLE_FILTER_FUNCTION_CONTRAST: u8 = 1;
const SIMPLE_FILTER_FUNCTION_GRAYSCALE: u8 = 2;
const SIMPLE_FILTER_FUNCTION_INVERT: u8 = 3;
const SIMPLE_FILTER_FUNCTION_OPACITY: u8 = 4;
const SIMPLE_FILTER_FUNCTION_SATURATE: u8 = 5;
const SIMPLE_FILTER_FUNCTION_SEPIA: u8 = 6;
const FONT_VARIANT_CALLBACK_NORMAL: u8 = 0;
const FONT_VARIANT_CALLBACK_SIMPLE: u8 = 1;
const FONT_VARIANT_CALLBACK_ALTERNATES_VALUE: u8 = 2;
const FONT_VARIANT_CALLBACK_ALTERNATES_FEATURE_VALUE_NAME: u8 = 3;
const FONT_VARIANT_CALLBACK_EAST_ASIAN_VALUE: u8 = 4;
const FONT_VARIANT_CALLBACK_NUMERIC_VALUE: u8 = 5;
const FONT_VARIANT_CALLBACK_LIGATURES_VALUE: u8 = 6;

fn callback_cursor_style_value<C>(callback: &mut C, property_id: u16, value: &RustOwnedCursor)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    for image in &value.images {
        callback(
            CssStyleValueKind::Cursor,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            CURSOR_CALLBACK_IMAGE,
            u8::from(image.x_source.is_some()),
            0,
            0,
            image.image_source.as_bytes(),
            &format!(
                "{}\0{}",
                image.x_source.as_deref().unwrap_or(""),
                image.y_source.as_deref().unwrap_or("")
            ),
        );
    }

    callback(
        CssStyleValueKind::Cursor,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        CURSOR_CALLBACK_PREDEFINED,
        0,
        0,
        0,
        value.predefined.as_bytes(),
        "",
    );
}

fn callback_filter_value_list_style_value<C>(callback: &mut C, property_id: u16, value: &RustOwnedFilterValueList)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match value {
        RustOwnedFilterValueList::None => callback(
            CssStyleValueKind::FilterValueList,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            FILTER_VALUE_LIST_CALLBACK_NONE,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedFilterValueList::Filters(filters) => {
            for filter in filters {
                match filter {
                    RustOwnedFilterValue::Url(source) => callback(
                        CssStyleValueKind::FilterValueList,
                        property_id,
                        CssPrimitiveValueKind::Invalid,
                        false,
                        0.0,
                        false,
                        0.0,
                        FILTER_VALUE_LIST_CALLBACK_URL,
                        0,
                        0,
                        0,
                        source.as_bytes(),
                        "",
                    ),
                    RustOwnedFilterValue::Blur { radius_source } => callback_optional_filter_source(
                        callback,
                        property_id,
                        FILTER_VALUE_LIST_CALLBACK_BLUR,
                        0,
                        radius_source.as_ref(),
                    ),
                    RustOwnedFilterValue::DropShadow {
                        color_source,
                        offset_x_source,
                        offset_y_source,
                        radius_source,
                    } => {
                        let secondary_source = format!(
                            "{}\0{}\0{}",
                            offset_y_source,
                            radius_source.as_deref().unwrap_or(""),
                            color_source.as_deref().unwrap_or("")
                        );
                        callback(
                            CssStyleValueKind::FilterValueList,
                            property_id,
                            CssPrimitiveValueKind::Invalid,
                            false,
                            0.0,
                            false,
                            0.0,
                            FILTER_VALUE_LIST_CALLBACK_DROP_SHADOW,
                            u8::from(radius_source.is_some()),
                            u8::from(color_source.is_some()),
                            0,
                            offset_x_source.as_bytes(),
                            &secondary_source,
                        );
                    }
                    RustOwnedFilterValue::HueRotate { angle_source } => callback_optional_filter_source(
                        callback,
                        property_id,
                        FILTER_VALUE_LIST_CALLBACK_HUE_ROTATE,
                        0,
                        angle_source.as_ref(),
                    ),
                    RustOwnedFilterValue::Simple {
                        function,
                        amount_source,
                    } => callback_optional_filter_source(
                        callback,
                        property_id,
                        FILTER_VALUE_LIST_CALLBACK_SIMPLE,
                        match function {
                            RustOwnedSimpleFilterFunction::Brightness => SIMPLE_FILTER_FUNCTION_BRIGHTNESS,
                            RustOwnedSimpleFilterFunction::Contrast => SIMPLE_FILTER_FUNCTION_CONTRAST,
                            RustOwnedSimpleFilterFunction::Grayscale => SIMPLE_FILTER_FUNCTION_GRAYSCALE,
                            RustOwnedSimpleFilterFunction::Invert => SIMPLE_FILTER_FUNCTION_INVERT,
                            RustOwnedSimpleFilterFunction::Opacity => SIMPLE_FILTER_FUNCTION_OPACITY,
                            RustOwnedSimpleFilterFunction::Saturate => SIMPLE_FILTER_FUNCTION_SATURATE,
                            RustOwnedSimpleFilterFunction::Sepia => SIMPLE_FILTER_FUNCTION_SEPIA,
                        },
                        amount_source.as_ref(),
                    ),
                }
            }
        }
    }
}

fn callback_optional_filter_source<C>(
    callback: &mut C,
    property_id: u16,
    kind: u8,
    secondary_kind: u8,
    source: Option<&String>,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        CssStyleValueKind::FilterValueList,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        kind,
        secondary_kind,
        u8::from(source.is_some()),
        0,
        source.map_or(&[], |source| source.as_bytes()),
        "",
    );
}

fn callback_font_variant_style_value<C>(callback: &mut C, property_id: u16, value: &FontVariant)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    if !value.has_any_value() {
        callback(
            CssStyleValueKind::FontVariant,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            FONT_VARIANT_CALLBACK_NORMAL,
            0,
            0,
            0,
            &[],
            "",
        );
        return;
    }

    if value.ligatures_none {
        callback_font_variant_simple_value(
            callback,
            property_id,
            CssFontVariantSimpleValueKind::LigaturesNone,
            None,
        );
    }
    if let Some(alternates) = &value.alternates {
        for value in alternates {
            callback(
                CssStyleValueKind::FontVariant,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                FONT_VARIANT_CALLBACK_ALTERNATES_VALUE,
                value.kind as u8,
                0,
                0,
                &[],
                "",
            );
            for feature_value_name in &value.feature_value_names {
                callback(
                    CssStyleValueKind::FontVariant,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    FONT_VARIANT_CALLBACK_ALTERNATES_FEATURE_VALUE_NAME,
                    0,
                    0,
                    0,
                    feature_value_name.as_bytes(),
                    "",
                );
            }
        }
    }
    if let Some(caps) = &value.caps {
        callback_font_variant_simple_value(callback, property_id, CssFontVariantSimpleValueKind::Caps, Some(caps));
    }
    if let Some(east_asian) = &value.east_asian {
        for value in east_asian {
            callback(
                CssStyleValueKind::FontVariant,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                FONT_VARIANT_CALLBACK_EAST_ASIAN_VALUE,
                value.kind as u8,
                0,
                0,
                value.value.as_bytes(),
                "",
            );
        }
    }
    if let Some(emoji) = &value.emoji {
        callback_font_variant_simple_value(callback, property_id, CssFontVariantSimpleValueKind::Emoji, Some(emoji));
    }
    if let Some(ligatures) = &value.ligatures {
        for value in ligatures {
            callback(
                CssStyleValueKind::FontVariant,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                FONT_VARIANT_CALLBACK_LIGATURES_VALUE,
                value.kind as u8,
                0,
                0,
                value.value.as_bytes(),
                "",
            );
        }
    }
    if let Some(numeric) = &value.numeric {
        for value in numeric {
            callback(
                CssStyleValueKind::FontVariant,
                property_id,
                CssPrimitiveValueKind::Invalid,
                false,
                0.0,
                false,
                0.0,
                FONT_VARIANT_CALLBACK_NUMERIC_VALUE,
                value.kind as u8,
                0,
                0,
                value.value.as_bytes(),
                "",
            );
        }
    }
    if let Some(position) = &value.position {
        callback_font_variant_simple_value(
            callback,
            property_id,
            CssFontVariantSimpleValueKind::Position,
            Some(position),
        );
    }
}

fn callback_font_variant_simple_value<C>(
    callback: &mut C,
    property_id: u16,
    kind: CssFontVariantSimpleValueKind,
    value: Option<&String>,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        CssStyleValueKind::FontVariant,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        FONT_VARIANT_CALLBACK_SIMPLE,
        kind as u8,
        0,
        0,
        value.map_or(&[], |value| value.as_bytes()),
        "",
    );
}

const POSITION_AREA_CALLBACK_NONE: u8 = 0;
const POSITION_AREA_CALLBACK_AREA: u8 = 1;
const POSITION_TRY_FALLBACK_CALLBACK_NONE: u8 = 0;
const POSITION_TRY_FALLBACK_CALLBACK_POSITION_AREA: u8 = 1;
const POSITION_TRY_FALLBACK_CALLBACK_TRY_TACTIC: u8 = 2;

fn callback_position_area_style_value<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    value: &RustOwnedPositionArea,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match value {
        RustOwnedPositionArea::None => callback(
            kind,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            POSITION_AREA_CALLBACK_NONE,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedPositionArea::Area {
            first_keyword,
            second_keyword,
        } => callback(
            kind,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            POSITION_AREA_CALLBACK_AREA,
            0,
            0,
            0,
            first_keyword.as_bytes(),
            second_keyword.as_deref().unwrap_or(""),
        ),
    }
}

fn callback_position_try_fallbacks_style_value<C>(
    callback: &mut C,
    property_id: u16,
    value: &RustOwnedPositionTryFallbacks,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match value {
        RustOwnedPositionTryFallbacks::None => callback(
            CssStyleValueKind::PositionTryFallbacks,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            POSITION_TRY_FALLBACK_CALLBACK_NONE,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedPositionTryFallbacks::List(fallbacks) => {
            for fallback in fallbacks {
                match fallback {
                    RustOwnedPositionTryFallback::PositionArea(value) => {
                        let RustOwnedPositionArea::Area {
                            first_keyword,
                            second_keyword,
                        } = value
                        else {
                            continue;
                        };
                        callback(
                            CssStyleValueKind::PositionTryFallbacks,
                            property_id,
                            CssPrimitiveValueKind::Invalid,
                            false,
                            0.0,
                            false,
                            0.0,
                            POSITION_TRY_FALLBACK_CALLBACK_POSITION_AREA,
                            0,
                            0,
                            0,
                            first_keyword.as_bytes(),
                            second_keyword.as_deref().unwrap_or(""),
                        );
                    }
                    RustOwnedPositionTryFallback::TryTactic {
                        dashed_ident,
                        has_flip_block,
                        has_flip_inline,
                        has_flip_start,
                    } => callback(
                        CssStyleValueKind::PositionTryFallbacks,
                        property_id,
                        CssPrimitiveValueKind::Invalid,
                        false,
                        0.0,
                        false,
                        0.0,
                        POSITION_TRY_FALLBACK_CALLBACK_TRY_TACTIC,
                        u8::from(*has_flip_block),
                        u8::from(*has_flip_inline),
                        u8::from(*has_flip_start),
                        dashed_ident.as_ref().map_or(&[], |value| value.as_bytes()),
                        "",
                    ),
                }
            }
        }
    }
}

const SHADOW_CALLBACK_NONE: u8 = 0;
const SHADOW_CALLBACK_BEGIN_SHADOW: u8 = 1;
const SHADOW_CALLBACK_COLOR: u8 = 2;
const SHADOW_CALLBACK_OFFSET_X: u8 = 3;
const SHADOW_CALLBACK_OFFSET_Y: u8 = 4;
const SHADOW_CALLBACK_BLUR_RADIUS: u8 = 5;
const SHADOW_CALLBACK_SPREAD_DISTANCE: u8 = 6;
const SHADOW_PLACEMENT_OUTER: u8 = 0;
const SHADOW_PLACEMENT_INNER: u8 = 1;

fn callback_shadow_style_value<C>(callback: &mut C, property_id: u16, value: &RustOwnedShadow)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    let mut callback_shadow_component = |component: u8, placement: u8, source: &str| {
        callback(
            CssStyleValueKind::Shadow,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            component,
            placement,
            0,
            0,
            source.as_bytes(),
            "",
        );
    };

    match value {
        RustOwnedShadow::None => callback_shadow_component(SHADOW_CALLBACK_NONE, 0, ""),
        RustOwnedShadow::Shadows(shadows) => {
            for shadow in shadows {
                let placement = match shadow.placement {
                    RustOwnedShadowPlacement::Outer => SHADOW_PLACEMENT_OUTER,
                    RustOwnedShadowPlacement::Inner => SHADOW_PLACEMENT_INNER,
                };
                callback_shadow_component(SHADOW_CALLBACK_BEGIN_SHADOW, placement, "");
                if let Some(color_source) = &shadow.color_source {
                    callback_shadow_component(SHADOW_CALLBACK_COLOR, 0, color_source);
                }
                callback_shadow_component(SHADOW_CALLBACK_OFFSET_X, 0, &shadow.offset_x_source);
                callback_shadow_component(SHADOW_CALLBACK_OFFSET_Y, 0, &shadow.offset_y_source);
                if let Some(blur_radius_source) = &shadow.blur_radius_source {
                    callback_shadow_component(SHADOW_CALLBACK_BLUR_RADIUS, 0, blur_radius_source);
                }
                if let Some(spread_distance_source) = &shadow.spread_distance_source {
                    callback_shadow_component(SHADOW_CALLBACK_SPREAD_DISTANCE, 0, spread_distance_source);
                }
            }
        }
    }
}

fn callback_transform_longhand_style_value<C>(callback: &mut C, property_id: u16, value: &RustOwnedTransformLonghand)
where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    match value {
        RustOwnedTransformLonghand::None => callback(
            CssStyleValueKind::TransformLonghand,
            property_id,
            CssPrimitiveValueKind::Invalid,
            false,
            0.0,
            false,
            0.0,
            0,
            0,
            0,
            0,
            &[],
            "",
        ),
        RustOwnedTransformLonghand::Function {
            function_name,
            arguments,
        } => {
            for (index, argument) in arguments.iter().enumerate() {
                callback(
                    CssStyleValueKind::TransformLonghand,
                    property_id,
                    CssPrimitiveValueKind::Invalid,
                    false,
                    0.0,
                    false,
                    0.0,
                    u8::try_from(index + 1).expect("transform longhands have fewer than 255 arguments"),
                    0,
                    0,
                    0,
                    argument.as_bytes(),
                    function_name,
                );
            }
        }
    }
}

fn callback_place_shorthand_style_value<C>(
    callback: &mut C,
    kind: CssStyleValueKind,
    property_id: u16,
    value: &RustOwnedPlaceShorthand,
) where
    C: FnMut(CssStyleValueKind, u16, CssPrimitiveValueKind, bool, f64, bool, f64, u8, u8, u8, u8, &[u8], &str),
{
    callback(
        kind,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        0,
        0,
        0,
        0,
        value.align_source.as_bytes(),
        "",
    );
    callback(
        kind,
        property_id,
        CssPrimitiveValueKind::Invalid,
        false,
        0.0,
        false,
        0.0,
        1,
        0,
        0,
        0,
        value.justify_source.as_bytes(),
        "",
    );
}

fn null_separated_string_list_bytes(strings: &[String]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for (index, string) in strings.iter().enumerate() {
        if index > 0 {
            bytes.push(0);
        }
        bytes.extend_from_slice(string.as_bytes());
    }
    bytes
}

fn null_terminated_timeline_name_item_bytes(items: &[RustOwnedTimelineNameItem]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for item in items {
        bytes.push(item.kind as u8);
        bytes.extend_from_slice(item.name.as_bytes());
        bytes.push(0);
    }
    bytes
}

fn null_terminated_animation_name_item_bytes(items: &[RustOwnedAnimationNameItem]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for item in items {
        bytes.push(item.kind as u8);
        bytes.extend_from_slice(item.value.as_bytes());
        bytes.push(0);
    }
    bytes
}

fn null_terminated_will_change_feature_bytes(features: &[RustOwnedWillChangeFeature]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for feature in features {
        bytes.push(feature.kind as u8);
        bytes.extend_from_slice(feature.value.as_bytes());
        bytes.push(0);
    }
    bytes
}

pub(crate) fn parse_coordinating_value_list_shorthand<C>(
    property_ids: &[u16],
    filtered_input: &[u8],
    mut callback: C,
) -> bool
where
    C: FnMut(usize, u16, &str),
{
    let Some(items) = parse_rust_owned_coordinating_value_list_shorthand(property_ids, filtered_input) else {
        return false;
    };

    for item in items {
        callback(item.layer_index, item.style_value.property_id as u16, &item.source);
    }

    true
}

pub(crate) fn parse_rust_owned_coordinating_value_list_shorthand(
    property_ids: &[u16],
    filtered_input: &[u8],
) -> Option<Vec<RustOwnedCoordinatingValueListShorthandItem>> {
    if property_ids.is_empty() {
        return None;
    }

    if !property_ids
        .iter()
        .all(|property_id| property_id_from_u16(*property_id).is_some())
    {
        return None;
    }

    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let mut parser = ComponentValueParser::new(component_values);
    let mut layer_index = 0;
    let mut items = Vec::new();

    // https://drafts.csswg.org/css-values-4/#comb-comma
    // A hash mark (#) indicates that the preceding type, word, or group occurs
    // one or more times, separated by comma tokens (which may optionally be
    // surrounded by white space and/or comments).
    loop {
        let mut remaining_property_ids = property_ids.to_vec();
        let mut parsed_any_value = false;

        loop {
            parser.discard_whitespace();
            if matches!(
                parser.next_component_value(),
                None | Some(ComponentValue::PreservedToken(Token {
                    token_type: TokenType::Comma,
                    ..
                }))
            ) {
                break;
            }

            let start = parser.index;
            parser.index += 1;
            let serialized_value = serialize_component_values_for_reparsing(
                &parser.component_values[start..parser.index],
                filtered_input_string,
            )?;

            let RustOwnedStyleValueParseResult::Parsed(style_value) =
                parse_rust_owned_style_value_for_property_with_mode(
                    &remaining_property_ids,
                    serialized_value.as_bytes(),
                    true,
                )
            else {
                return None;
            };
            let matched_property_id = style_value.property_id as u16;

            if !remaining_property_ids.contains(&matched_property_id) {
                return None;
            };

            remaining_property_ids.retain(|property_id| *property_id != matched_property_id);
            items.push(RustOwnedCoordinatingValueListShorthandItem {
                layer_index,
                style_value,
                source: serialized_value,
            });
            parsed_any_value = true;
        }

        if !parsed_any_value {
            return None;
        }

        parser.discard_whitespace();
        if !parser.consume_a_comma() {
            break;
        }

        layer_index += 1;
    }

    parser.discard_whitespace();
    if parser.has_next_component_value() {
        return None;
    }

    Some(items)
}

pub(crate) fn parse_positional_value_list_shorthand<C>(property_id: u16, filtered_input: &[u8], mut callback: C) -> bool
where
    C: FnMut(usize, &str),
{
    let Some(items) = parse_rust_owned_positional_value_list_shorthand(property_id, filtered_input) else {
        return false;
    };

    for item in items {
        callback(item.index, &item.source);
    }

    true
}

pub(crate) fn parse_rust_owned_positional_value_list_shorthand(
    property_id: u16,
    filtered_input: &[u8],
) -> Option<Vec<RustOwnedPositionalValueListShorthandItem>> {
    let property_id = property_id_from_u16(property_id)?;
    if !property_is_positional_value_list_shorthand(property_id) {
        return None;
    }

    let longhands = longhands_for_shorthand(property_id);
    if !matches!(longhands.len(), 2 | 4) {
        return None;
    }

    let property_ids = [property_id as u16];
    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let mut parser = ComponentValueParser::new(component_values);
    let mut values = Vec::new();

    loop {
        parser.discard_whitespace();
        if !parser.has_next_component_value() {
            break;
        }
        if values.len() == longhands.len() {
            return None;
        }

        let start = parser.index;
        parser.index += 1;
        let serialized_value = serialize_component_values_for_reparsing(
            &parser.component_values[start..parser.index],
            filtered_input_string,
        )?;

        let RustOwnedStyleValueParseResult::Parsed(style_value) =
            parse_rust_owned_style_value_for_property(&property_ids, serialized_value.as_bytes())
        else {
            return None;
        };
        values.push(RustOwnedPositionalValueListShorthandItem {
            index: values.len(),
            style_value,
            source: serialized_value,
        });
    }

    if values.is_empty() {
        return None;
    }

    Some(values)
}

fn style_value_numeric_value(value_type: PropertyValueType, component_values: &[ComponentValue]) -> Option<f64> {
    if value_type == PropertyValueType::Ratio {
        return style_value_ratio_values(value_type, component_values).map(|(numerator, _)| numerator);
    }

    let [ComponentValue::PreservedToken(token)] = component_values else {
        return None;
    };

    match (&token.token_type, value_type) {
        (TokenType::Number { number }, PropertyValueType::Integer) if number_is_integer(*number) => {
            Some(number.value())
        }
        (TokenType::Number { number }, PropertyValueType::Number | PropertyValueType::OpacityValue) => {
            Some(number.value())
        }
        (TokenType::Percentage { number }, PropertyValueType::Percentage | PropertyValueType::OpacityValue) => {
            Some(number.value())
        }
        (TokenType::Dimension { number, .. }, PropertyValueType::Length | PropertyValueType::Time) => {
            Some(number.value())
        }
        (TokenType::Number { number }, PropertyValueType::Length) if number.value() == 0.0 => Some(0.0),
        _ => None,
    }
}

fn style_value_secondary_numeric_value(
    value_type: PropertyValueType,
    component_values: &[ComponentValue],
) -> Option<f64> {
    style_value_ratio_values(value_type, component_values).map(|(_, denominator)| denominator)
}

fn style_value_ratio_values(value_type: PropertyValueType, component_values: &[ComponentValue]) -> Option<(f64, f64)> {
    if value_type != PropertyValueType::Ratio {
        return None;
    }

    let component_values = strip_whitespace(component_values);
    match component_values {
        [
            ComponentValue::PreservedToken(Token {
                token_type: TokenType::Number { number },
                ..
            }),
        ] if number.value() >= 0.0 => Some((number.value(), 1.0)),
        _ => {
            let (slash_index, _) = component_values.iter().enumerate().find(|(_, component_value)| {
                matches!(
                    component_value,
                    ComponentValue::PreservedToken(Token {
                        token_type: TokenType::Delim { value },
                        ..
                    }) if *value == '/' as u32
                )
            })?;

            let numerator = strip_whitespace(&component_values[..slash_index]);
            let denominator = strip_whitespace(&component_values[slash_index + 1..]);
            let [
                ComponentValue::PreservedToken(Token {
                    token_type: TokenType::Number { number: numerator },
                    ..
                }),
            ] = numerator
            else {
                return None;
            };
            let [
                ComponentValue::PreservedToken(Token {
                    token_type: TokenType::Number { number: denominator },
                    ..
                }),
            ] = denominator
            else {
                return None;
            };

            (numerator.value() >= 0.0 && denominator.value() >= 0.0).then_some((numerator.value(), denominator.value()))
        }
    }
}

fn style_value_ratio_has_denominator(value_type: PropertyValueType, component_values: &[ComponentValue]) -> bool {
    if value_type != PropertyValueType::Ratio {
        return false;
    }

    style_value_ratio_values(value_type, component_values).is_some()
        && component_values_parse_as_ratio_with_denominator(component_values)
}

fn style_value_dimension_unit(value_type: PropertyValueType, component_values: &[ComponentValue]) -> Option<&str> {
    let [ComponentValue::PreservedToken(token)] = component_values else {
        return None;
    };

    match (&token.token_type, value_type) {
        (TokenType::Dimension { unit, .. }, PropertyValueType::Length | PropertyValueType::Time) => Some(unit),
        (TokenType::Number { number }, PropertyValueType::Length) if number.value() == 0.0 => Some("px"),
        _ => None,
    }
}

fn style_value_primitive_kind(
    value_type: PropertyValueType,
    component_values: &[ComponentValue],
) -> CssPrimitiveValueKind {
    if value_type == PropertyValueType::Ratio {
        return if style_value_ratio_values(value_type, component_values).is_some() {
            CssPrimitiveValueKind::Ratio
        } else {
            CssPrimitiveValueKind::Invalid
        };
    }

    let [component_value] = component_values else {
        return CssPrimitiveValueKind::Invalid;
    };

    match value_type {
        PropertyValueType::Integer => parse_integer_value_prefix(component_value),
        PropertyValueType::Number => parse_number_value_prefix(component_value),
        PropertyValueType::Length => parse_length_value_prefix(component_value, CssPrimitiveValueOptions::default()),
        PropertyValueType::Time => parse_time_value_prefix(component_value),
        PropertyValueType::Percentage => parse_percentage_value_prefix(component_value),
        PropertyValueType::String => parse_string_value_prefix(component_value),
        PropertyValueType::OpacityValue => match parse_number_value_prefix(component_value) {
            CssPrimitiveValueKind::Number => CssPrimitiveValueKind::Number,
            _ => parse_percentage_value_prefix(component_value),
        },
        _ => CssPrimitiveValueKind::Invalid,
    }
}

fn string_token_value(component_values: &[ComponentValue]) -> Option<&str> {
    let [
        ComponentValue::PreservedToken(Token {
            token_type: TokenType::String { value },
            ..
        }),
    ] = component_values
    else {
        return None;
    };

    Some(value)
}

fn generated_property_value_type_order() -> &'static [PropertyValueType] {
    // This follows Parser::parse_css_value_for_properties(), which is ordered to
    // preserve CSS grammar precedence, for example <integer>/<number> before
    // <length> so a unitless zero is not captured as a length when both are
    // accepted.
    &[
        PropertyValueType::Anchor,
        PropertyValueType::Color,
        PropertyValueType::CornerShape,
        PropertyValueType::Counter,
        PropertyValueType::CounterStyle,
        PropertyValueType::DashedIdent,
        PropertyValueType::EasingFunction,
        PropertyValueType::FontStyle,
        PropertyValueType::FontKerningValue,
        PropertyValueType::FontOpticalSizingValue,
        PropertyValueType::FontWeightAbsolute,
        PropertyValueType::FontWidthCss3,
        PropertyValueType::FontVariantAlternates,
        PropertyValueType::FontVariantCapsValue,
        PropertyValueType::FontVariantEastAsian,
        PropertyValueType::FontVariantEmojiValue,
        PropertyValueType::FontVariantLigatures,
        PropertyValueType::FontVariantNumeric,
        PropertyValueType::FontVariantPositionValue,
        PropertyValueType::Image,
        PropertyValueType::Position,
        PropertyValueType::BackgroundPosition,
        PropertyValueType::BasicShape,
        PropertyValueType::Ratio,
        PropertyValueType::OpacityValue,
        PropertyValueType::OpentypeTag,
        PropertyValueType::Rect,
        PropertyValueType::ScrollFunction,
        PropertyValueType::String,
        PropertyValueType::TransformList,
        PropertyValueType::Url,
        PropertyValueType::ViewFunction,
        PropertyValueType::ViewTimelineInset,
        PropertyValueType::Integer,
        PropertyValueType::Number,
        PropertyValueType::FitContent,
        PropertyValueType::Length,
        PropertyValueType::Time,
        PropertyValueType::Percentage,
        PropertyValueType::Paint,
    ]
}

fn component_values_parse_as_property_value_type(value_type: PropertyValueType, filtered_input: &[u8]) -> bool {
    match value_type {
        PropertyValueType::Anchor => rust_owned_anchor_function_style_value_kind(filtered_input).is_some(),
        PropertyValueType::Color => parse_color_value(filtered_input, false) == CssColorValueKind::Valid,
        PropertyValueType::Counter => rust_owned_counter_function_style_value_kind(filtered_input).is_some(),
        PropertyValueType::DashedIdent => parse_a_dashed_ident(filtered_input, |_| {}),
        PropertyValueType::EasingFunction => parse_easing_value(filtered_input) == CssEasingValueKind::Valid,
        PropertyValueType::FitContent => parse_fit_content_value(filtered_input) == CssFitContentValueKind::Valid,
        PropertyValueType::BasicShape => parse_basic_shape_value(filtered_input) == CssBasicShapeValueKind::Valid,
        PropertyValueType::CounterStyle => parse_a_counter_style(filtered_input, |_, _, _| {}, |_| {}),
        PropertyValueType::FontStyle => parse_a_font_style(filtered_input, |_| {}),
        PropertyValueType::FontVariantAlternates => parse_a_font_variant_alternates(filtered_input, |_| {}, |_| {}),
        PropertyValueType::FontVariantEastAsian => parse_a_font_variant_east_asian(filtered_input, |_| {}),
        PropertyValueType::FontVariantLigatures => parse_a_font_variant_ligatures(filtered_input, |_| {}),
        PropertyValueType::FontVariantNumeric => parse_a_font_variant_numeric(filtered_input, |_| {}),
        PropertyValueType::Position => parse_position_value(filtered_input, false) == CssPositionValueKind::Valid,
        PropertyValueType::BackgroundPosition => {
            parse_position_value(filtered_input, true) == CssPositionValueKind::Valid
        }
        PropertyValueType::Ratio => parse_ratio_value_prefix(filtered_input).kind == CssRatioValueKind::Valid,
        PropertyValueType::OpacityValue => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Opacity,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Opacity
        }
        PropertyValueType::OpentypeTag => parse_an_opentype_tag(filtered_input, |_| {}),
        PropertyValueType::Rect => parse_rect_value(filtered_input) == CssRectValueKind::Valid,
        PropertyValueType::ScrollFunction => {
            parse_scroll_function_value(filtered_input).kind == CssScrollFunctionValueKind::Valid
        }
        PropertyValueType::String => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::String,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::String
        }
        PropertyValueType::TransformList => parse_transform_list_value(filtered_input),
        // AD-HOC: Keep <url> on the C++ fallback path until Rust owns <image>
        // materialization as well. Some properties accept both <image> and <url>,
        // and C++ deliberately parses non-fragment url() values as images first.
        PropertyValueType::Url => false,
        PropertyValueType::ViewFunction => {
            parse_view_function_value(filtered_input).kind == CssViewFunctionValueKind::Valid
        }
        PropertyValueType::ViewTimelineInset => {
            parse_view_timeline_inset_value(filtered_input).kind == CssViewTimelineInsetValueKind::Valid
        }
        PropertyValueType::Integer => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Integer,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Integer
        }
        PropertyValueType::Number => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Number,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Number
        }
        PropertyValueType::Length => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Length,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Length
        }
        PropertyValueType::Time => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Time,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Time
        }
        PropertyValueType::Percentage => {
            parse_primitive_value(
                filtered_input,
                CssPrimitiveValueType::Percentage,
                CssPrimitiveValueOptions::default(),
            ) == CssPrimitiveValueKind::Percentage
        }
        PropertyValueType::FontKerningValue => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontKerningValue, filtered_input)
        }
        PropertyValueType::FontOpticalSizingValue => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontOpticalSizingValue, filtered_input)
        }
        PropertyValueType::FontWeightAbsolute => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontWeightAbsolute, filtered_input)
        }
        PropertyValueType::FontWidthCss3 => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontWidthCss3, filtered_input)
        }
        PropertyValueType::FontVariantCapsValue => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontVariantCapsValue, filtered_input)
        }
        PropertyValueType::FontVariantEmojiValue => {
            component_values_parse_as_generated_property_value_type(ValueTypeId::FontVariantEmojiValue, filtered_input)
        }
        PropertyValueType::FontVariantPositionValue => component_values_parse_as_generated_property_value_type(
            ValueTypeId::FontVariantPositionValue,
            filtered_input,
        ),
        PropertyValueType::Image => {
            rust_owned_image_style_value_kind(filtered_input, &filtered_input_to_string(filtered_input)).is_some()
        }
        _ => false,
    }
}

fn generated_value_type_id_for_property_value_type(value_type: PropertyValueType) -> Option<ValueTypeId> {
    match value_type {
        PropertyValueType::FontKerningValue => Some(ValueTypeId::FontKerningValue),
        PropertyValueType::FontOpticalSizingValue => Some(ValueTypeId::FontOpticalSizingValue),
        PropertyValueType::FontWeightAbsolute => Some(ValueTypeId::FontWeightAbsolute),
        PropertyValueType::FontWidthCss3 => Some(ValueTypeId::FontWidthCss3),
        PropertyValueType::FontVariantCapsValue => Some(ValueTypeId::FontVariantCapsValue),
        PropertyValueType::FontVariantEmojiValue => Some(ValueTypeId::FontVariantEmojiValue),
        PropertyValueType::FontVariantPositionValue => Some(ValueTypeId::FontVariantPositionValue),
        _ => None,
    }
}

fn component_values_parse_as_generated_property_value_type(value_type_id: ValueTypeId, filtered_input: &[u8]) -> bool {
    parse_a_value_type(filtered_input, value_type_id as u8) != CssValueTypeSyntaxKind::Invalid
}

fn parse_transform_list_value(filtered_input: &[u8]) -> bool {
    // https://drafts.csswg.org/css-transforms-1/#typedef-transform-list
    // <transform-list> = <transform-function>+
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let component_values = strip_whitespace(&component_values);
    if component_values.is_empty() {
        return false;
    }

    component_values
        .iter()
        .filter(|component_value| !is_whitespace_component_value(component_value))
        .all(|component_value| {
            let ComponentValue::Function(function) = component_value else {
                return false;
            };
            component_value_parse_as_transform_function(function)
        })
}

fn component_value_parse_as_transform_function(function: &Function) -> bool {
    let Some(parameters) = transform_function_parameters_from_name(&function.name) else {
        return false;
    };

    let Some(arguments) = parse_comma_separated_component_values(function.value.clone(), |component_values| {
        let [component_value] = strip_whitespace(&component_values) else {
            return None;
        };
        Some(component_value.clone())
    }) else {
        return false;
    };

    if arguments.len() > parameters.len() {
        return false;
    }
    if arguments.len() < parameters.len() && parameters[arguments.len()].required {
        return false;
    }

    arguments.iter().zip(parameters).all(|(argument, parameter)| {
        component_value_matches_transform_function_parameter(argument, parameter.parameter_type)
    })
}

fn numeric_range_limit_to_f64(limit: Option<f64>, value_type: PropertyValueType, is_minimum: bool) -> f64 {
    match (limit, value_type, is_minimum) {
        (Some(limit), _, _) => limit,
        (None, PropertyValueType::Integer, true) => i32::MIN as f64,
        (None, PropertyValueType::Integer, false) => i32::MAX as f64,
        (None, _, true) => f32::MIN as f64,
        (None, _, false) => f32::MAX as f64,
    }
}

fn numeric_range_to_f64(range: PropertyNumericRange, value_type: PropertyValueType) -> (f64, f64) {
    (
        numeric_range_limit_to_f64(range.minimum, value_type, true),
        numeric_range_limit_to_f64(range.maximum, value_type, false),
    )
}

pub(crate) fn property_numeric_metadata<C>(property_ids: &[u16], value_type: &[u8], mut callback: C) -> bool
where
    C: FnMut(u16, f64, f64, bool, f64, f64, bool),
{
    let Ok(value_type) = std::str::from_utf8(value_type) else {
        return false;
    };
    let Some(value_type) = property_value_type_from_css_value_type_name(value_type) else {
        return false;
    };

    for property_id in property_ids {
        let Some(property_id) = property_id_from_u16(*property_id) else {
            continue;
        };
        if !property_accepts_value_type(property_id, value_type) {
            continue;
        }
        let Some(range) = property_accepted_range_by_value_type(property_id, value_type) else {
            continue;
        };

        let (minimum, maximum) = numeric_range_to_f64(range, value_type);
        let percentages_resolve_to_value_type =
            property_resolves_percentages_relative_to(property_id) == Some(value_type);
        if percentages_resolve_to_value_type {
            let Some(percentage_range) =
                property_accepted_range_by_value_type(property_id, PropertyValueType::Percentage)
            else {
                continue;
            };
            let (percentage_minimum, percentage_maximum) =
                numeric_range_to_f64(percentage_range, PropertyValueType::Percentage);
            callback(
                property_id as u16,
                minimum,
                maximum,
                true,
                percentage_minimum,
                percentage_maximum,
                true,
            );
            return true;
        }

        callback(property_id as u16, minimum, maximum, false, 0.0, 0.0, false);
        return true;
    }

    false
}

fn parse_as_syntax_string(input: &str, limit_single_component_ident_to_custom_ident: bool) -> Option<SyntaxNode> {
    let (mut parser, _) = parser_from_filtered_input(input.as_bytes());
    let component_values = parser.parse_a_list_of_component_values();
    component_values_parse_as_syntax_with_source(
        &component_values,
        limit_single_component_ident_to_custom_ident,
        Some(input),
    )
}

pub(crate) fn parse_as_syntax<C>(
    filtered_input: &[u8],
    limit_single_component_ident_to_custom_ident: bool,
    mut callback: C,
) where
    C: FnMut(CssSyntaxNode),
{
    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let Some(syntax_node) = component_values_parse_as_syntax_with_source(
        &component_values,
        limit_single_component_ident_to_custom_ident,
        Some(filtered_input_string),
    ) else {
        callback(CssSyntaxNode::new(CssSyntaxNodeKind::Invalid));
        return;
    };

    emit_syntax_node(&syntax_node, &mut callback);
}

pub(crate) fn parse_syntax_component_prefix<C>(
    filtered_input: &[u8],
    limit_single_component_ident_to_custom_ident: bool,
    mut callback: C,
) -> usize
where
    C: FnMut(CssSyntaxNode),
{
    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let mut parser = ComponentValueParser::new(component_values);
    let Some(syntax_node) = parse_syntax_component(
        &mut parser,
        limit_single_component_ident_to_custom_ident,
        Some(filtered_input_string),
    ) else {
        callback(CssSyntaxNode::new(CssSyntaxNodeKind::Invalid));
        return 0;
    };

    let Some(consumed_input) =
        serialize_component_values_for_reparsing(&parser.component_values[..parser.index], filtered_input_string)
    else {
        callback(CssSyntaxNode::new(CssSyntaxNodeKind::Invalid));
        return 0;
    };

    emit_syntax_node(&syntax_node, &mut callback);
    consumed_input.len()
}

pub(crate) fn parse_css_type_prefix<C>(
    filtered_input: &[u8],
    limit_single_component_ident_to_custom_ident: bool,
    mut callback: C,
) -> usize
where
    C: FnMut(CssSyntaxNode),
{
    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    let component_values = parser.parse_a_list_of_component_values();
    let mut parser = ComponentValueParser::new(component_values);
    let Some(syntax_node) = parse_css_type(
        &mut parser,
        limit_single_component_ident_to_custom_ident,
        Some(filtered_input_string),
    ) else {
        callback(CssSyntaxNode::new(CssSyntaxNodeKind::Invalid));
        return 0;
    };

    let Some(consumed_input) =
        serialize_component_values_for_reparsing(&parser.component_values[..parser.index], filtered_input_string)
    else {
        callback(CssSyntaxNode::new(CssSyntaxNodeKind::Invalid));
        return 0;
    };

    emit_syntax_node(&syntax_node, &mut callback);
    consumed_input.len()
}

pub(crate) fn parse_a_supports_condition<E, C>(
    filtered_input: &[u8],
    mut event_callback: E,
    mut component_value_callback: C,
) where
    E: FnMut(CssBooleanExpressionEventKind),
    C: FnMut(CssComponentValue),
{
    let (mut parser, filtered_input_string) = parser_from_filtered_input(filtered_input);
    parser.rule_context.push(RuleContext::SupportsCondition);
    let component_values = parser.parse_a_list_of_component_values();
    parser.rule_context.pop();

    let mut parser = ComponentValueParser::new(component_values);
    if parser
        .parse_a_boolean_expression(BooleanExpressionTestKind::SupportsFeature)
        .is_none()
        || parser.has_next_component_value()
    {
        event_callback(CssBooleanExpressionEventKind::Invalid);
        return;
    }

    let boolean_expression = parser
        .boolean_expression
        .take()
        .expect("parsed expression must be present");
    emit_boolean_expression(
        &boolean_expression,
        filtered_input_string,
        &mut event_callback,
        &mut component_value_callback,
        &mut |_| {},
        &mut |_| {},
    );
}

pub(crate) fn parse_a_supports_feature<F>(filtered_input: &[u8], mut feature_callback: F) -> bool
where
    F: FnMut(CssSupportsFeatureKind, Option<&str>),
{
    let (mut parser, _) = parser_from_filtered_input(filtered_input);
    parser.rule_context.push(RuleContext::SupportsCondition);
    let component_values = parser.parse_a_list_of_component_values();
    parser.rule_context.pop();

    let mut parser = ComponentValueParser::new(component_values);
    parser.discard_whitespace();
    let Some((feature, _)) = parser.parse_supports_feature_syntax() else {
        return false;
    };

    parser.discard_whitespace();
    if parser.has_next_component_value() {
        return false;
    }

    match feature {
        SupportsFeature::Declaration => feature_callback(CssSupportsFeatureKind::Declaration, None),
        SupportsFeature::Selector => feature_callback(CssSupportsFeatureKind::Selector, None),
        SupportsFeature::FontTech(name) => feature_callback(CssSupportsFeatureKind::FontTech, Some(&name)),
        SupportsFeature::FontFormat(name) => feature_callback(CssSupportsFeatureKind::FontFormat, Some(&name)),
        SupportsFeature::Env(name) => feature_callback(CssSupportsFeatureKind::Env, Some(&name)),
    }

    true
}

